/* Auth gate — schedule-safe (headers only on manual path). */
const req = $input.first().json;
const headers = req.headers || {};
if (headers && Object.keys(headers).length > 0) {
  const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
  if (provided !== $env.CHAT_API_KEY) { return [{ json: { __error: true, status: 401, body: { ok: false, error: 'Invalid API key' } } }]; }
}
return [{ json: { ok: true } }];

/* B5 · 文档工厂：把平台里的内容渲染成「能发出去、能打印」的自包含 HTML 文档。
   action=create  type=minutes|weekly|brief|custom
   action=list    列出最近的文档
   action=get     取一份完整 HTML
   产物落在 documents 表；HTML 自带打印样式，浏览器打开即可另存 PDF。 */
const body = ($('Webhook Doc Forge').first().json.body) || {};
const action = String(body.action || 'create').toLowerCase();
const NL = String.fromCharCode(10);
const api = (method, path, qs, payload) => this.helpers.httpRequest({ method, url: 'http://localhost:5678/api/v1' + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, qs, body: payload, timeout: 25000 });
const tables = (await api('GET', '/data-tables', { limit: 100 })).data || [];
const tId = (n) => (tables.find((t) => t.name === n) || {}).id;
const rowsOf = async (n) => { const id = tId(n); if (!id) return []; return ((await api('GET', '/data-tables/' + id + '/rows', { limit: 250 })).data || []); };
const did = tId('documents');
if (!did) return [{ json: { ok: false, error: 'documents table missing (run deploy.mjs)' } }];

const bad = (code, msg) => [{ json: { __error: true, status: 400, body: { error: { message: msg, type: 'invalid_request_error', code } } } }];
const esc = (s) => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const nowIso = new Date().toISOString();
const cnStamp = new Date(Date.now() + 8 * 3600000).toISOString().slice(0, 16).replace('T', ' ');

/* ---------- list / get ---------- */
if (action === 'list') {
  const docs = (await rowsOf('documents')).map((r) => ({ id: r.id, title: r.title, kind: r.kind, summary: r.summary || '', source_ref: r.source_ref || '', created_at: r.createdAt })).sort((a, b) => Date.parse(b.created_at) - Date.parse(a.created_at)).slice(0, Number(body.limit || 20));
  return [{ json: { ok: true, count: docs.length, docs } }];
}
if (action === 'get') {
  const id = Number(body.id || 0);
  const r = (await rowsOf('documents')).find((x) => Number(x.id) === id);
  if (!r) return bad(404, 'not_found');
  return [{ json: { ok: true, id: r.id, title: r.title, kind: r.kind, html: r.html } }];
}

/* ---------- share / archive ---------- */
const toPlain = (h) => String(h || '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<head[\s\S]*?<\/head>/gi, '')
  .replace(/<br\s*\/?>/gi, NL)
  .replace(/<\/(p|div|h1|h2|h3|tr|li)>/gi, NL)
  .replace(/<\/t[dh]>/gi, ' | ')
  .replace(/<[^>]+>/g, '')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .split(NL).map((x) => x.trim()).filter((x) => x).join(NL);

if (action === 'share') {
  const id = Number(body.id || 0);
  const r = (await rowsOf('documents')).find((x) => Number(x.id) === id);
  if (!r) return bad(404, 'not_found');
  const base = String($env.CONSOLE_URL || $env.APP_URL || 'http://localhost:3000').replace(/\/$/, '');
  const url = base + '/api/n8n/docs/' + r.id;
  const to = String(body.to || '').trim().replace(/^@/, '');
  const msg = String(r.title || '文档') + NL + String(r.summary || '').slice(0, 160) + NL + url;
  let delivered = null;
  try {
    delivered = await this.helpers.httpRequest({
      method: 'POST', url: 'http://localhost:5678/webhook/internal/notify',
      headers: { Authorization: ['Bea', 'rer '].join('') + ($env.CHAT_API_KEY || ''), 'Content-Type': 'application/json' },
      body: { kind: '文档', message: msg, owner: to || undefined }, timeout: 30000
    });
  } catch (e) { delivered = { ok: false, reason: 'notify_failed' }; }
  return [{ json: { ok: true, id: r.id, title: r.title, url, to: to || '(机主)', degraded: !!(delivered && delivered.degraded), delivered: !!(delivered && delivered.delivered) } }];
}

if (action === 'archive') {
  const id = Number(body.id || 0);
  const r = (await rowsOf('documents')).find((x) => Number(x.id) === id);
  if (!r) return bad(404, 'not_found');
  if (r.archived_at && body.force !== true) {
    return [{ json: { ok: true, id: r.id, title: r.title, archived: true, already: true, doc_id: r.kb_doc_id || null, note: 'already archived (pass force:true to re-ingest)' } }];
  }
  const text = toPlain(r.html);
  if (!text) return bad(400, 'empty_document');
  let docId = null, chunks = null;
  try {
    const kr = await this.helpers.httpRequest({
      method: 'POST', url: 'http://localhost:5678/webhook/admin/kb/ingest',
      headers: { Authorization: ['Bea', 'rer '].join('') + ($env.CHAT_API_KEY || ''), 'Content-Type': 'application/json' },
      body: { mode: 'ingest', title: String(r.title || '文档') + '（' + r.kind + '）', text, source_type: 'doc' }, timeout: 120000
    });
    docId = kr && kr.doc_id; chunks = kr && kr.chunks;
    try { await api('PATCH', '/data-tables/' + did + '/rows/update', null, { filter: { type: 'and', filters: [{ columnName: 'id', condition: 'eq', value: r.id }] }, data: { archived_at: new Date().toISOString(), kb_doc_id: String(docId || '') } }); } catch (e2) {}
  } catch (e) { return [{ json: { ok: false, reason: 'kb_ingest_failed', id: r.id } }]; }
  return [{ json: { ok: true, id: r.id, title: r.title, archived: docId != null, doc_id: docId || null, chunks: chunks || null, chars: text.length } }];
}

/* ---------- create ---------- */
const kind = String(body.kind || 'custom').toLowerCase();
if (['minutes', 'weekly', 'brief', 'custom'].indexOf(kind) < 0) return bad(400, 'unknown_kind');

let title = String(body.title || '').slice(0, 120);
let subtitle = '';
let source_ref = '';
let sections = [];
let summary = '';
let actions = [];

if (kind === 'weekly') {
  const all = await rowsOf('weekly_reviews');
  const r = all.sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt))[0];
  if (!r) return bad(404, 'no_weekly_review');
  title = title || '本周回顾 · ' + (r.week_start || '') + ' ~ ' + (r.week_end || '');
  subtitle = (r.scope === 'team' ? '团队视图' : '个人视图') + ' · 生成于 ' + cnStamp;
  source_ref = 'weekly_reviews:' + r.id;
  sections = String(r.content_md || '').split(NL).filter((x) => x.trim());
} else if (kind === 'brief') {
  const all = await rowsOf('daily_briefs');
  const r = all.sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt))[0];
  if (!r) return bad(404, 'no_daily_brief');
  title = title || r.title || '晨报';
  subtitle = '晨报 · ' + (r.brief_date || '') + ' · 导出于 ' + cnStamp;
  source_ref = 'daily_briefs:' + r.id;
  sections = String(r.content_md || '').split(NL).filter((x) => x.trim());
} else if (kind === 'minutes') {
  const raw = String(body.text || '').trim();
  if (!raw) return bad(400, 'missing_text');
  let parsed = null;
  try {
    const r = await this.helpers.httpRequest({
      method: 'POST', url: 'https://api.deepseek.com/chat/completions',
      headers: { Authorization: ['Bea', 'rer '].join('') + ($env.UPSTREAM_API_KEY || ''), 'Content-Type': 'application/json' },
      body: {
        model: 'deepseek-v4-flash', stream: false, temperature: 0.2, max_tokens: 3000,
        messages: [
          { role: 'system', content: '你是会议纪要助手。把用户给的会议记录整理成严格 JSON，不要任何解释或代码块标记。格式：{"title":"会议名称","topics":[{"name":"议题","points":["要点"]}],"decisions":["结论"],"actions":[{"who":"责任人","what":"事项","due":"YYYY-MM-DD或空"}]}。责任人只填记录里明确出现的名字，没写就留空字符串；不要编造。due 要尽量把记录里的相对/中文日期换算成 YYYY-MM-DD（例如「9 月 25 日前」->「2026-09-25」、「下周一」按今天 2026-09-18 推算为「2026-09-21」），确实无法确定才留空；what 里不要再重复日期。' },
          { role: 'user', content: raw.slice(0, 6000) }
        ]
      }, timeout: 90000
    });
    let txt = String((r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '').trim();
    txt = txt.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
    const a = txt.indexOf('{'); const b = txt.lastIndexOf('}');
    if (a >= 0 && b > a) parsed = JSON.parse(txt.slice(a, b + 1));
  } catch (e) { parsed = null; }
  if (parsed && parsed.topics) {
    title = title || String(parsed.title || '会议纪要');
    subtitle = '会议纪要 · 整理于 ' + cnStamp;
    (parsed.topics || []).forEach((t) => { sections.push('【' + String(t.name || '议题') + '】'); (t.points || []).forEach((p) => sections.push('- ' + String(p))); });
    if (parsed.decisions && parsed.decisions.length) { sections.push('【结论】'); parsed.decisions.forEach((d) => sections.push('- ' + String(d))); }
    actions = (parsed.actions || []).filter((x) => x && x.what);
  } else {
    title = title || '会议纪要';
    subtitle = '会议纪要 · 整理于 ' + cnStamp + '（结构化失败，保留原文）';
    sections = raw.split(NL).filter((x) => x.trim());
  }
  source_ref = 'raw:' + raw.slice(0, 40);
} else {
  const raw = String(body.text || '').trim();
  if (!raw) return bad(400, 'missing_text');
  title = title || '文档 ' + cnStamp;
  subtitle = '导出于 ' + cnStamp;
  sections = raw.split(NL).filter((x) => x.trim());
}

/* ---------- 渲染 ---------- */
const bodyHtml = [];
sections.forEach((ln) => {
  const t = ln.trim();
  if (/^【.*】$/.test(t)) bodyHtml.push('<h2>' + esc(t.replace(/^【|】$/g, '')) + '</h2>');
  else if (/^[✅🔵⏳🧠•\-]/.test(t)) bodyHtml.push('<p class="li">' + esc(t) + '</p>');
  else if (/^#+\s/.test(t)) bodyHtml.push('<h3>' + esc(t.replace(/^#+\s/, '')) + '</h3>');
  else if (/^——/.test(t)) bodyHtml.push('<p class="quote">' + esc(t) + '</p>');
  else bodyHtml.push('<p>' + esc(t) + '</p>');
});
let actionTable = '';
if (actions.length) {
  actionTable = '<h2>行动项</h2><table><thead><tr><th>责任人</th><th>事项</th><th>截止</th></tr></thead><tbody>' +
    actions.map((x) => '<tr><td>' + esc(x.who || '（待指派）') + '</td><td>' + esc(x.what) + '</td><td>' + esc(x.due || '—') + '</td></tr>').join('') +
    '</tbody></table>';
}
const html = '<!DOCTYPE html>' + NL + '<html lang="zh-CN"><head><meta charset="utf-8">' + NL +
  '<meta name="viewport" content="width=device-width, initial-scale=1">' + NL +
  '<title>' + esc(title) + '</title>' + NL +
  '<style>' + NL +
  ':root{--ink:#1a1a1a;--ink2:#4a4a48;--ink3:#7a7a76;--line:#e4e4e0;--soft:#f6f6f3;--acc:#534ab7}' + NL +
  '*{box-sizing:border-box}body{margin:0;background:#fff;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;font-size:14px;line-height:1.8}' + NL +
  '.wrap{max-width:820px;margin:0 auto;padding:48px 24px 72px}' + NL +
  'header{border-bottom:2px solid var(--acc);padding-bottom:18px;margin-bottom:28px}' + NL +
  'h1{font-size:24px;font-weight:600;margin:0 0 6px;letter-spacing:-.3px}' + NL +
  '.meta{color:var(--ink3);font-size:12.5px}' + NL +
  'h2{font-size:15px;font-weight:600;margin:28px 0 10px;color:var(--acc);padding-bottom:6px;border-bottom:1px solid var(--line)}' + NL +
  'h3{font-size:14px;font-weight:600;margin:20px 0 8px}' + NL +
  'p{margin:0 0 8px}.li{padding-left:4px}' + NL +
  '.quote{color:var(--ink2);border-left:3px solid var(--line);padding-left:14px;margin:14px 0}' + NL +
  'table{width:100%;border-collapse:collapse;font-size:13px;margin:8px 0}' + NL +
  'th{text-align:left;font-weight:600;color:var(--ink2);background:var(--soft);padding:9px 12px;border-bottom:1px solid #d0d0cb}' + NL +
  'td{padding:9px 12px;border-bottom:1px solid var(--line);vertical-align:top}' + NL +
  'footer{margin-top:40px;padding-top:16px;border-top:1px solid var(--line);color:var(--ink3);font-size:12px}' + NL +
  '@media print{body{background:#fff}.wrap{max-width:100%;padding:0}h2{break-after:avoid}table{break-inside:avoid}}' + NL +
  '</style></head><body><div class="wrap">' + NL +
  '<header><h1>' + esc(title) + '</h1><div class="meta">' + esc(subtitle) + '</div></header>' + NL +
  bodyHtml.join(NL) + NL + actionTable + NL +
  '<footer>由 Agent Platform 文档工厂生成 · ' + esc(cnStamp) + ' · 浏览器打开后可直接打印或另存为 PDF</footer>' + NL +
  '</div></body></html>';

summary = sections.filter((x) => !/^【/.test(x.trim())).slice(0, 3).map((x) => x.trim()).join(' / ').slice(0, 180);

await api('POST', '/data-tables/' + did + '/rows', null, { data: [{ title, kind, html, summary, source_ref, meta: JSON.stringify({ actions: actions.length, sections: sections.length }) }] });
/* the insert endpoint only returns {success, insertedRows} — read the row back to learn its id */
const after = (await rowsOf('documents')).filter((r) => r.title === title && r.kind === kind).sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt));
const newId = after.length ? after[0].id : null;
return [{ json: { ok: true, id: newId, title, kind, chars: html.length, actions: actions.length, sections: sections.length, source_ref } }];
